mapper.select:
SELECT c.cart_id AS cartId, c.quantity AS quantity, c.cart_type AS cartType, c.user_id AS userId, c.product_id AS productId, c.option_item_id AS optionItemId, c.rental_start AS rentalStart, c.rental_end AS rentalEnd, p.product_name AS productName, p.price AS price, b.brand_name AS brandName, (p.price + COALESCE(poi.extra_price, 0)) AS unitPrice, COALESCE(poi.item_name, '기본 옵션') AS optionName, COALESCE(poi.extra_price, 0) AS optionPrice, ( SELECT img_url FROM product_img WHERE product_id = c.product_id AND is_main = 'Y' LIMIT 1 ) AS imgUrl FROM cart c INNER JOIN product p ON c.product_id = p.product_id LEFT JOIN brand b ON p.brand_id = b.brand_id LEFT JOIN product_option_item poi ON c.option_item_id = poi.option_item_id WHERE c.user_id = #{userId}
AND c.cart_id IN (${cartIds})
ORDER BY c.created_at DESC

mapper.insert:
INSERT INTO ORDERS ( ORDER_TYPE, ORDER_STATUS, TOTAL_PRICE, DISCOUNT_AMT, CREATED_AT, USER_ID, USER_COUPON_ID, GUEST_NAME, GUEST_PHONE, CART_IDS ) VALUES ( #{cartType}, 'READY', #{amount}, #{discountAmt}, NOW(), #{userId},
#{userCouponId}
NULL , #{guestName}, #{guestPhone}, #{cartIds} )

mapper.update:
UPDATE ORDERS
SET ORDER_STATUS = #{orderStatus}
WHERE ORDER_ID = #{orderId}

mapper.delete:
DELETE FROM CART
WHERE FIND_IN_SET(
CART_ID,
(SELECT CART_IDS FROM ORDERS WHERE ORDER_ID = #{orderId})
) > 0
AND USER_ID = #{userId}

mapper.insert:
INSERT INTO POINT_HISTORY (
USER_ID, DESCRIPTION, AMOUNT, TYPE, CREATED_AT, BALANCE_AFTER
) VALUES (
#{userId},
#{description},
#{earnedPoint},
'EARN',
NOW(),
(
SELECT COALESCE(POINT, 0) + #{earnedPoint}
FROM USER
WHERE USER_ID = #{userId}
)
)

mapper.update:
UPDATE USER
SET POINT = POINT + #{earnedPoint},
TOTAL_AMOUNT = TOTAL_AMOUNT + #{amount}
WHERE USER_ID = #{userId}

 UPDATE
		product_stock SET TOTAL_QTY = TOTAL_QTY - #{quantity}, AVAILABLE_QTY =
		AVAILABLE_QTY - #{quantity} WHERE PRODUCT_ID = #{productId} 
			AND OPTION_ITEM_ID = #{optionItemId}
		 AND TOTAL_QTY
		>= #{quantity} AND AVAILABLE_QTY >= #{quantity}

 UPDATE
		product_stock SET RESERVED_QTY = RESERVED_QTY + #{quantity},
		AVAILABLE_QTY = AVAILABLE_QTY - #{quantity} WHERE PRODUCT_ID =
		#{productId} 
			AND OPTION_ITEM_ID = #{optionItemId}
		 AND STOCK_DATE
		BETWEEN #{startDate} AND DATE_SUB(#{endDate}, INTERVAL 1 DAY) AND
		AVAILABLE_QTY >= #{quantity}
